// мягкие золотые частицы, поднимающиеся вверх, и лёгкий туман внизу
const N = 70;
const particles = [];
for (let i=0;i<N;i++){
  particles.push({
    x: Math.random()*W(),
    y: H()*0.15 + Math.random()*H()*0.25,
    r: 0.6+Math.random()*2.2,
    vy: -(0.08+Math.random()*0.18),
    vx: (Math.random()-0.5)*0.05,
    phase: Math.random()*Math.PI*2,
    speed: 0.004+Math.random()*0.006,
    alpha: 0.2+Math.random()*0.5
  });
}

const mistN = 40;
const mist = [];
for (let i=0;i<mistN;i++){
  mist.push({
    x: Math.random()*W(),
    y: H()*0.72 + Math.random()*H()*0.26,
    r: 20+Math.random()*60,
    vx: (Math.random()-0.5)*0.03,
    phase: Math.random()*Math.PI*2,
    speed: 0.002+Math.random()*0.003,
    alpha: 0.03+Math.random()*0.05
  });
}

let t = 0;
function frame(){
  t += 1;
  ctx.clearRect(0,0,W(),H());

  // холодный туман внизу
  for (const m of mist){
    m.phase += m.speed;
    m.x += m.vx;
    if (m.x < -m.r) m.x = W()+m.r;
    if (m.x > W()+m.r) m.x = -m.r;
    const wob = Math.sin(m.phase)*6;
    const g = ctx.createRadialGradient(m.x, m.y+wob, 0, m.x, m.y+wob, m.r);
    g.addColorStop(0, 'rgba(143,163,199,' + m.alpha + ')');
    g.addColorStop(1, 'rgba(143,163,199,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(m.x, m.y+wob, m.r, 0, Math.PI*2);
    ctx.fill();
  }

  // золотые частицы, поднимающиеся от коврижки
  for (const p of particles){
    p.phase += p.speed;
    p.y += p.vy;
    p.x += p.vx + Math.sin(p.phase)*0.15;
    if (p.y < H()*0.05){
      p.y = H()*0.4 + Math.random()*H()*0.15;
      p.x = Math.random()*W();
    }
    const flicker = 0.6 + 0.4*Math.sin(p.phase*2);
    ctx.save();
    ctx.globalAlpha = p.alpha*flicker;
    ctx.shadowColor = 'rgba(217,164,65,0.8)';
    ctx.shadowBlur = 6;
    ctx.fillStyle = '#d9a441';
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  }

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
